CREATE INDEX IX_Orders_OrderDate ON dbo.Orders(OrderDate);

-- Query A
SELECT * FROM dbo.Orders WHERE YEAR(OrderDate) = 2023;

-- Query B
SELECT * FROM dbo.Orders WHERE OrderDate >= '2023-01-01' AND OrderDate < '2024-01-01';

